import{_ as t,l,o as r,c as o,v as e,p as n,x as s,d,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"Kruskal 与 Prim","description":"","frontmatter":{"title":"Kruskal 与 Prim","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mst-kruskal-prim.md","filePath":"cs/mst-kruskal-prim.md","lastUpdated":1789023840000}'),u={name:"cs/mst-kruskal-prim.md"};function h(c,a,k,E,P,_){const i=l("Mermaid");return r(),o("div",null,[a[1]||(a[1]=e('<h1 id="kruskal-与-prim" tabindex="-1">Kruskal 与 Prim <a class="header-anchor" href="#kruskal-与-prim" aria-label="Permalink to &quot;Kruskal 与 Prim&quot;">​</a></h1><div class="epigraph"><p>连通无向图上，边权之和最小的生成树可以由安全边逐步长成：要么在森林间加最轻边，要么从一棵树向外长。</p><footer>—— 据 Kruskal, On the Shortest Spanning Subtree, 1956；Prim, Shortest Connection Networks, 1957；CLRS 第 23 章整理</footer></div><p>上一课<a href="/cs/johnson-apsp">Johnson 全源</a>给了点对距离。最小生成树问的是另一件事：用 \\(|V|-1\\) 条边连通、总权最小。本课不重做全源。缺口是：<strong>安全边</strong>——加进去不破坏某棵 MST 的前缀。<a href="/cs/union-find">并查集</a>与堆已在。本课交出 Kruskal 与 Prim。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无向连通、边权可比较（可负；负环不是 MST 的语言）。切分定理：对任意切分，横跨切分的最轻边是某 MST 的安全边。Kruskal：边按权排序，若两端不在同一连通块则加入（并查集）。Prim：从一棵树出发，反复加树到外部的最轻边（优先队列）。</p><p>与 Dijkstra 酷似但目标不同：Prim 的键是「到树的边权」，不是「到源的路权」。不要把 MST 当最短路树。</p><h3 id="两种贪心同一套切分" tabindex="-1">两种贪心同一套切分 <a class="header-anchor" href="#两种贪心同一套切分" aria-label="Permalink to &quot;两种贪心同一套切分&quot;">​</a></h3><p>Kruskal 的切分是当前森林的块；Prim 的切分是树内/树外。切分定理共用。正确性走贪心的安全边，一般贪心模板在<a href="/cs/greedy-correct">后课</a>，本课先把 MST 做成实例。</p><p><span class="marginnote">Kruskal 1956、Prim 1957（Borůvka 1926 更早，本课点名第三算法但不实现）。并查集加路径压缩与按秩，Kruskal 几乎是 \\(O(E\\log V)\\) 排序主导。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Kruskal：排序 \\(E\\)，对每条边 <code>Find</code> 两端，不同则 <code>Union</code> 并收录。Prim：类似 Dijkstra 的循环，松弛的是树外顶点到树的最小边权。</p>',11)),(r(),n(p,null,{default:s(()=>[m(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E8%BF%9E%E9%80%9A%E6%97%A0%E5%90%91%E5%9B%BE%22%5D%20--%3E%20K%5B%22Kruskal%EF%BC%9A%E6%8E%92%E5%BA%8F%20%2B%20%E5%B9%B6%E6%9F%A5%E9%9B%86%22%5D%0A%20%20G%20--%3E%20P%5B%22Prim%EF%BC%9A%E6%A0%91%E5%90%91%E5%A4%96%20%2B%20%E5%A0%86%22%5D%0A%20%20K%20--%3E%20MST%5B%22%E6%9C%80%E5%B0%8F%E7%94%9F%E6%88%90%E6%A0%91%22%5D%0A%20%20P%20--%3E%20MST%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>不连通则生成森林。本课默认连通。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>稀疏图 Kruskal 常更干净（排序一次）。稠密 Prim 用邻接矩阵扫描可 \\(O(V^2)\\)。唯一性：边权互异则 MST 唯一；否则可以多棵，算法给出其中一棵。最大生成树把权取负即可，仍是本课。</p><p>与最短路：负权对 MST 无妨（无向且不走环累加定义）。Dijkstra 仍要非负。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理有向图的最小树形图（Edmonds/Chu–Liu）。不写度约束、Steiner 树——那些或 NP 或另一模型。后课最大流换成容量与割，不是生成树。</p><p>后课默认：MST = Kruskal 或 Prim；切分定理保证贪心安全。流网络是下一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>切分上的最轻边安全；Kruskal 并查集，Prim 长树。</li><li>稀疏常 Kruskal \\(O(E\\log V)\\)；稠密 Prim \\(O(V^2)\\)。</li><li>MST 不是最短路树；负权可接受。</li><li>出处：Kruskal, 1956；Prim, 1957；CLRS 第 23 章。</li></ul>',9))])}const f=t(u,[["render",h]]);export{T as __pageData,f as default};
